        int fd = open("/dev/urandom", O_RDONLY);
        if (fd < 0) {
            free(buf);
            runtime_error_raise("random_bytes could not read secure random bytes", 1003, "random");
            return value_null();
        }
        size_t off = 0;
        while (off < n) {
            ssize_t c = read(fd, buf + off, n - off);
            if (c < 0 && errno == EINTR) {
                continue;
            }
            if (c <= 0) {
                close(fd);
                free(buf);
                runtime_error_raise("random_bytes could not read secure random bytes", 1003, "random");
                return value_null();
            }
            off += (size_t)c;
        }
        close(fd);
        Value r = value_string_n((char *)buf, n);
        free(buf);
        return r;
